api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.welcome-section {
  background: #f0fdfa;
  padding: 70px 20px;
}

.welcome-container {
  max-width: 1200px;
  margin: auto;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 60px;
}

.welcome-content {
  max-width: 680px;
}

.welcome-tag {
  display: inline-flex;

  gap: 8px;

  padding: 7px 13px;

  border-radius: 20px;

  background: #ccfbf1;
  color: #0f766e;

  font-size: 13px;
  font-weight: 600;
}

.welcome-content h1 {
  margin-top: 18px;

  font-size: 44px;
  line-height: 1.15;

  color: #111827;
}

.welcome-content p {
  margin-top: 18px;

  font-size: 17px;
  line-height: 1.7;

  color: #4b5563;
}

.welcome-buttons {
  display: flex;
  gap: 14px;

  margin-top: 28px;
}

.primary-btn,
.secondary-btn {
  padding: 12px 20px;

  border-radius: 8px;

  text-decoration: none;

  font-weight: 600;
}

.primary-btn {
  background: #0f766e;
  color: white;
}

.secondary-btn {
  border: 1px solid #0f766e;
  color: #0f766e;
  background: white;
}

.welcome-card {
  width: 300px;

  padding: 35px;

  background: white;

  border-radius: 18px;

  box-shadow: 0 10px 30px rgba(0,0,0,0.08);

  text-align: center;
}

.food-icon {
  width: 70px;
  height: 70px;

  margin: auto;

  border-radius: 50%;

  background: #ccfbf1;
  color: #0f766e;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 28px;
}

.welcome-card h3 {
  margin-top: 20px;
}

.welcome-card p {
  color: #6b7280;
  line-height: 1.6;
}

sp_widget.script:
(function() {

    data.loggedIn = gs.isLoggedIn();

    data.title =
        'A Better Way to Manage Campus Food Services';

    data.description =
        'Report food-related issues, track complaints, ' +
        'follow resolutions and share feedback through ' +
        'one simple platform.';

})();
